'use strict';
const previewSpaceStyle=document.createElement('style');previewSpaceStyle.textContent='@media(min-width:850px){body main{grid-template-columns:190px minmax(320px,1fr) 230px;grid-template-rows:minmax(260px,1fr) 260px}body .workspace{padding:10px 12px 0;min-width:0}body .library,body .inspector{padding:12px 10px}body.preview-hide-library main{grid-template-columns:0 minmax(320px,1fr) 230px}body.preview-hide-inspector main{grid-template-columns:190px minmax(320px,1fr) 0}body.preview-hide-library.preview-hide-inspector main{grid-template-columns:0 minmax(320px,1fr) 0}body.preview-hide-library .library,body.preview-hide-inspector .inspector{visibility:hidden;padding:0;border:0;overflow:hidden}body .paperstage{display:flex;justify-content:center;align-items:center;min-height:100px;padding:6px}body .stagebar{margin-bottom:5px}body .canvasfooter{min-height:30px;padding:4px 0}body .studio-toolbar{min-height:32px;margin-bottom:4px}body .timeline-body{min-height:50px}}';document.head.append(previewSpaceStyle);
for(const [id,text,key]of [['togglePreviewLibrary','Library','preview-hide-library'],['togglePreviewInspector','Inspector','preview-hide-inspector']]){const b=storyButton(text,()=>{document.body.classList.toggle(key);b.setAttribute('aria-pressed',String(!document.body.classList.contains(key)));try{localStorage.setItem(key,String(document.body.classList.contains(key)))}catch{}layoutProjectFormat()});b.id=id;b.setAttribute('aria-pressed','true');document.querySelector('.stage-actions').append(b);try{if(localStorage.getItem(key)==='true'){document.body.classList.add(key);b.setAttribute('aria-pressed','false')}}catch{}}
const focusPreview=storyButton('Focus preview',()=>{const focus=!document.body.classList.contains('preview-hide-library')||!document.body.classList.contains('preview-hide-inspector');for(const key of ['preview-hide-library','preview-hide-inspector'])document.body.classList.toggle(key,focus);focusPreview.textContent=focus?'Show panels':'Focus preview';layoutProjectFormat()});focusPreview.id='focusPreview';document.querySelector('.stage-actions').append(focusPreview);
